hooks.extraMethods:
; Descrição do Produto
;
; set descricao=$$DescricaoProduto^WDOMTESTEPV100ATAB2RG(codEmpresa,codProduto)
DescricaoProduto(codEmpresa,codProduto)	;
$$$VAR
new sc,cgigen
;
if $get(codProduto)="" quit ""
set sc=$$VerItemCGIGEN^CCCGIRG001(codEmpresa,codProduto,.cgigen)
if $$$ISERR(sc) quit ""
;
quit $piece(cgigen,Z,1)
;
; Unidade de Medida do Produto
;
; set unidade=$$UnidadeProduto^WDOMTESTEPV100ATAB2RG(codEmpresa,codProduto)
UnidadeProduto(codEmpresa,codProduto)	;
$$$VAR
new sc,cgigen
;
if $get(codProduto)="" quit ""
set sc=$$VerItemCGIGEN^CCCGIRG001(codEmpresa,codProduto,.cgigen)
if $$$ISERR(sc) quit ""
;
quit $piece(cgigen,Z,2)
;
; Disponível do produto nos estoques da configuração (quando exibir = S)
;
; set disponivel=$$DisponivelProduto^WDOMTESTEPV100ATAB2RG(codEmpresa,codProduto)
DisponivelProduto(codEmpresa,codProduto)	;
$$$VAR
new sc,codNatureza,disponivel,total,mensagem
;
if $get(codProduto)="" quit ""
if $piece($get(^WDOMTESTEPVPDCFG(1,codEmpresa,1)),Z,3)'="S" quit ""
set (codNatureza,total)=""
for  set codNatureza=$order(^WDOMTESTEPVPDCFG(1,codEmpresa,1,1,codNatureza)) quit:codNatureza=""  do
. set disponivel=0
. set sc=$$VerSaldoDisponivel^CCESARG001(codEmpresa,codProduto,codNatureza,+$horolog,.disponivel,.mensagem)
. if $$$ISOK(sc) set total=total+disponivel
;
quit $select(total="":"",1:total/1000)

fields.valcpCode:
if {reference}="" quit $$$OK
set CSCI="",sc=$$VerCidade^CCAPLRG001({reference},.CSCI)
if $$$ISOK(sc) set CIDCLI=$piece(CSCI,Z,1)_"/"_$piece(CSCI,Z,2) do Set^%CSW1UTI(%PRG,"cp1700",CIDCLI)

ruleHooks.extraMethods:
; Obter Próximo Pedido do Representante (não reaproveita)
;
; set sc=$$ObterProximoPedido^WDOMTESTEPV100ARG(codEmpresa,.codPedido)
ObterProximoPedido(codEmpresa,codPedido)	;
$$$VAR
;
set codPedido=$increment(^WDOMTESTEPVPD(1,codEmpresa,0))
;
quit $$$OK
;
; Número do pedido para exibir: R<representante>-<pedido>
;
; set numero=$$NumeroPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido)
NumeroPedido(codEmpresa,codPedido)	;
$$$VAR
;
if $get(codPedido)="" quit ""
;
quit "R"_$piece($get(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)),Z,5)_"-"_codPedido
;
; Descrição do status
;
; set descricao=$$DescricaoStatus^WDOMTESTEPV100ARG(status)
DescricaoStatus(status)	;
$$$VAR
;
quit $case($get(status),"R":"Rascunho","C":"Confirmado","I":"Indeferido","E":"Enviado","F":"Faturado","X":"Cancelado",:"Rascunho")
;
; Tabela de status (lista fixa para filtros)
;
; set sc=$$ObterTabStatus^WDOMTESTEPV100ARG(.tabStatus)
ObterTabStatus(tabStatus)	;
$$$VAR
;
kill tabStatus
set tabStatus("R")="Rascunho",tabStatus("C")="Confirmado",tabStatus("I")="Indeferido"
set tabStatus("E")="Enviado",tabStatus("F")="Faturado",tabStatus("X")="Cancelado"
;
quit $$$OK
;
; Configuração do usuário (WDOMTESTEPV100C): admin e representantes
; admin = 1: comercial (pode enviar/indeferir e vê todos)
; restrito = 1: usuário configurado como representante e não admin (só os dele)
; Usuário sem configuração não é restrito.
;
; set sc=$$ObterConfigUsuario^WDOMTESTEPV100ARG(codEmpresa,codUsuario,.admin,.tabRepresentante,.restrito)
ObterConfigUsuario(codEmpresa,codUsuario,admin,tabRepresentante,restrito)	;
$$$VAR
new seq,dados,configurado
;
set (admin,restrito,configurado)=0
kill tabRepresentante
set seq=""
for  set seq=$order(^WDOMTESTEPVPDCFG(1,codEmpresa,2,seq)) quit:seq=""  do
. set dados=$get(^WDOMTESTEPVPDCFG(1,codEmpresa,2,seq))
. quit:$piece(dados,Z,3)'=codUsuario
. set configurado=1
. if $piece(dados,Z,5)="S" set admin=1
. if $piece(dados,Z,4)'="" set tabRepresentante($piece(dados,Z,4))=""
;
set restrito=configurado&&'admin
;
quit $$$OK
;
; Representante padrão do usuário (primeiro configurado)
;
; set codRepresentante=$$RepresentanteUsuario^WDOMTESTEPV100ARG(codEmpresa,codUsuario)
RepresentanteUsuario(codEmpresa,codUsuario)	;
$$$VAR
new sc,admin,tabRepresentante
;
set sc=$$ObterConfigUsuario(codEmpresa,codUsuario,.admin,.tabRepresentante)
;
quit $order(tabRepresentante(""))
;
; Validar Representante do pedido para o usuário (representante só usa os dele)
;
; set sc=$$ValidarRepresentanteUsuario^WDOMTESTEPV100ARG(codEmpresa,codRepresentante,codUsuario)
ValidarRepresentanteUsuario(codEmpresa,codRepresentante,codUsuario)	;
$$$VAR
new sc,admin,tabRepresentante,restrito
;
if $get(codRepresentante)="" quit $$$OK
set sc=$$ObterConfigUsuario(codEmpresa,codUsuario,.admin,.tabRepresentante,.restrito)
if 'restrito quit $$$OK
if '$data(tabRepresentante(codRepresentante)) quit $$$ERROR(10000,"Representante "_codRepresentante_" não está vinculado ao seu usuário!")
;
quit $$$OK
;
; Validar se o pedido pode ser alterado pelo representante
;
; set sc=$$ValidarPedidoEditavel^WDOMTESTEPV100ARG(codEmpresa,codPedido)
ValidarPedidoEditavel(codEmpresa,codPedido)	;
$$$VAR
new status
;
set status=$piece($get(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido))),Z,3)
if status="E"!(status="F")!(status="X") quit $$$ERROR(10000,"Pedido "_$$NumeroPedido(codEmpresa,codPedido)_" está "_$$DescricaoStatus(status)_" e não pode ser alterado!")
;
quit $$$OK
;
; Obter Dados do Cliente: nome^razão social^CNPJ/CPF^endereço^bairro^CEP^cidade/UF
; Com código: do cadastro (FTCL). Sem código: da global do pedido (nó 2).
;
; set sc=$$ObterDadosCliente^WDOMTESTEPV100ARG(codEmpresa,codPedido,codCliente,.dadosCliente)
ObterDadosCliente(codEmpresa,codPedido,codCliente,dadosCliente)	;
$$$VAR
new sc,ftcl,csci
;
set dadosCliente=""
if $get(codCliente)'="" do  quit sc
. set sc=$$VerCliente^CCFTRG001(codEmpresa,codCliente,.ftcl)
. quit:$$$ISERR(sc)
. set csci="" if $piece(ftcl,Z,6)'="" set sc=$$VerCidade^CCAPLRG001($piece(ftcl,Z,6),.csci)
. set dadosCliente=$select($piece(ftcl,Z,15)'="":$piece(ftcl,Z,15),1:$piece(ftcl,Z,2))_Z_$piece(ftcl,Z,2)_Z_$piece(ftcl,Z,7)_Z_$piece(ftcl,Z,3)_$select($piece(ftcl,Z,52)'="":", "_$piece(ftcl,Z,52),1:"")
. set dadosCliente=dadosCliente_Z_$piece(ftcl,Z,4)_Z_$piece(ftcl,Z,6)_Z_$select(csci="":"",1:$piece(csci,Z,1)_"/"_$piece(csci,Z,2))
. set sc=$$$OK
;
set dadosCliente=$piece($get(^WDOMTESTEPVPD(1,codEmpresa,2,+$get(codPedido))),Z,3,9)
;
quit $$$OK
;
; Limite de crédito disponível do cliente (texto formatado)
;
; set limite=$$LimiteDisponivel^WDOMTESTEPV100ARG(codEmpresa,codCliente)
LimiteDisponivel(codEmpresa,codCliente)	;
$$$VAR
;
new sc,limite,pedidosAbertos,dupChequesAbertos
;
if $get(codCliente)="" quit ""
set (limite,pedidosAbertos,dupChequesAbertos)=0
set sc=$$VerLimitePedidosPendencias^CCCCCRG002(%index,$get(%conta),codEmpresa,codCliente,.limite,.pedidosAbertos,.dupChequesAbertos)
if $$$ISERR(sc) quit ""
;
quit $fnumber((limite-pedidosAbertos-dupChequesAbertos)/100,".",2)
;
; Valor total do pedido (soma dos itens)
;
; set total=$$ValorTotalPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido)
ValorTotalPedido(codEmpresa,codPedido)	;
$$$VAR
new codItem,total
;
set (codItem,total)=0
for  set codItem=$order(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido),1,codItem)) quit:codItem=""  set total=total+($piece(^(codItem),Z,4)*$piece(^(codItem),Z,5))
;
quit total
;
; Gravar dados complementares do pedido (chamado no Gravar): cliente sem
; código (nó 2) e índices por representante (98) e pedido Consistem (99)
;
; set sc=$$GravarComplementoPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido,dados,dadosCliente)
GravarComplementoPedido(codEmpresa,codPedido,dados,dadosCliente)	;
$$$VAR
new dataHora,codOperador,anterior
;
set dataHora=$$$horologEmp(codEmpresa)
set codOperador=$$VEROP^%CSUTIUD(1)
set anterior=$get(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido))
;
if $piece(dados,Z,7)="" do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,2,codPedido),dataHora_Z_codOperador_Z_$piece($get(dadosCliente),Z,1,7))
if $piece(dados,Z,7)'="" do $$$KillG(^WDOMTESTEPVPD(1,codEmpresa,2,codPedido))
;
if $piece(anterior,Z,5)'="",$piece(anterior,Z,5)'=$piece(dados,Z,5) do $$$KillG(^WDOMTESTEPVPD(1,codEmpresa,98,$piece(anterior,Z,5),codPedido))
if $piece(dados,Z,5)'="" do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,98,$piece(dados,Z,5),codPedido),dataHora_Z_codOperador_Z_$piece(dados,Z,7))
if $piece(dados,Z,4)'="" do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,99,$piece(dados,Z,4)),codPedido)
;
quit $$$OK
;
; Gravar Histórico do Pedido (foto da capa, cliente e itens depois da ação)
;
; set sc=$$GravarHistoricoPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido,acao,observacao)
GravarHistoricoPedido(codEmpresa,codPedido,acao,observacao)	;
$$$VAR
new dataHora,codItem
;
if $get(codPedido)="" quit $$$OK
set dataHora=$$$horologEmp(codEmpresa)
for  quit:'$data(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora))  set $piece(dataHora,",",2)=$piece(dataHora,",",2)+1
;
do $$$SetG(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora),dataHora_Z_$$VEROP^%CSUTIUD(1)_Z_$get(acao)_Z_$translate($get(observacao),"^"," "))
do $$$SetG(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora,1),$get(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)))
do $$$SetG(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora,2),$get(^WDOMTESTEPVPD(1,codEmpresa,2,codPedido)))
set codItem=""
for  set codItem=$order(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido,1,codItem)) quit:codItem=""  do
. do $$$SetG(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora,3,codItem),dataHora_Z_$$VEROP^%CSUTIUD(1)_Z_$get(acao))
. do $$$SetG(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora,3,codItem,1),^WDOMTESTEPVPD(1,codEmpresa,1,codPedido,1,codItem))
;
quit $$$OK
;
; Atualizar total do pedido e gravar o histórico depois do Salvar
;
; set sc=$$FinalizarGravacaoPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido,acao)
FinalizarGravacaoPedido(codEmpresa,codPedido,acao)	;
$$$VAR
new dados
;
if '$data(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido))) quit $$$OK
set dados=^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)
set $piece(dados,Z,16)=$$ValorTotalPedido(codEmpresa,codPedido)
do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido),dados)
;
quit $$GravarHistoricoPedido(codEmpresa,codPedido,acao,"")
;
; Confirmar Pedido (representante): Rascunho/Indeferido -> Confirmado
;
; set sc=$$ConfirmarPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido)
ConfirmarPedido(codEmpresa,codPedido)	;
$$$VAR
new dados
;
if '$data(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido))) quit $$$ERROR(10000,"Salve o pedido antes de confirmar!")
if $order(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido,1,""))="" quit $$$ERROR(10000,"Informe os itens do pedido antes de confirmar!")
set dados=^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)
if "RI"'[$piece(dados,Z,3) quit $$$ERROR(10000,"Pedido "_$$NumeroPedido(codEmpresa,codPedido)_" está "_$$DescricaoStatus($piece(dados,Z,3))_"!")
;
set $piece(dados,Z,3)="C"
do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido),dados)
;
quit $$GravarHistoricoPedido(codEmpresa,codPedido,"Confirmar","")
;
; Indeferir Pedido (comercial): exige observação
;
; set sc=$$IndeferirPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido,observacao)
IndeferirPedido(codEmpresa,codPedido,observacao)	;
$$$VAR
new sc,admin,tabRepresentante,dados
;
set sc=$$ObterConfigUsuario(codEmpresa,$$VEROP^%CSUTIUD(1),.admin,.tabRepresentante)
if 'admin quit $$$ERROR(10000,"Somente usuários do comercial podem indeferir pedidos!")
if '$data(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido))) quit $$$ERROR(10000,"Selecione um pedido!")
if $translate($get(observacao)," ")="" quit $$$ERROR(10000,"Observação: Campo obrigatório!")
set dados=^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)
if "EFX"[$piece(dados,Z,3) quit $$$ERROR(10000,"Pedido "_$$NumeroPedido(codEmpresa,codPedido)_" está "_$$DescricaoStatus($piece(dados,Z,3))_"!")
;
set $piece(dados,Z,3)="I"
do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido),dados)
;
quit $$GravarHistoricoPedido(codEmpresa,codPedido,"Indeferido",observacao)
;
; Última observação de indeferimento (complemento mostrado no cadastro)
;
; set observacao=$$ObservacaoIndeferimento^WDOMTESTEPV100ARG(codEmpresa,codPedido)
ObservacaoIndeferimento(codEmpresa,codPedido)	;
$$$VAR
new dataHora,achou
;
set (dataHora,achou)=""
for  set dataHora=$order(^WDOMTESTEPVPDHIS(1,codEmpresa,1,+$get(codPedido),dataHora),-1) quit:dataHora=""!(achou'="")  do
. if $piece(^WDOMTESTEPVPDHIS(1,codEmpresa,1,codPedido,dataHora),Z,3)="Indeferido" set achou=$piece(^(dataHora),Z,4)
;
quit achou
;
; Enviar Pedido (comercial): gera o pedido no Consistem e vincula
;
; set sc=$$EnviarPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido)
EnviarPedido(codEmpresa,codPedido)	;
$$$VAR
new sc,admin,tabRepresentante,dados,codPedidoConsistem
;
set sc=$$ObterConfigUsuario(codEmpresa,$$VEROP^%CSUTIUD(1),.admin,.tabRepresentante)
if 'admin quit $$$ERROR(10000,"Somente usuários do comercial podem enviar pedidos para o Consistem!")
if '$data(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido))) quit $$$ERROR(10000,"Selecione um pedido!")
set dados=^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)
if $piece(dados,Z,3)'="C" quit $$$ERROR(10000,"Somente pedido Confirmado pode ser enviado!")
;
set codPedidoConsistem=""
set sc=$$GerarPedidoConsistem(codEmpresa,codPedido,.codPedidoConsistem)
if $$$ISERR(sc) quit sc
;
set $piece(dados,Z,3)="E"
set $piece(dados,Z,4)=codPedidoConsistem
do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido),dados)
do $$$SetG(^WDOMTESTEPVPD(1,codEmpresa,99,codPedidoConsistem),codPedido)
;
quit $$GravarHistoricoPedido(codEmpresa,codPedido,"Enviar","Pedido Consistem "_codPedidoConsistem)
;
; Gerar Pedido no Consistem (capa + itens do pedido do representante)
;
; set sc=$$GerarPedidoConsistem^WDOMTESTEPV100ARG(codEmpresa,codPedido,.codPedidoConsistem)
GerarPedidoConsistem(codEmpresa,codPedido,codPedidoConsistem)	;
$$$VAR
;
new sc,dados,cfg,tabCapa,tabErros,codItem,item,seq,term,erro
;
set codPedidoConsistem=""
set dados=$get(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido))
set cfg=$get(^WDOMTESTEPVPDCFG(1,codEmpresa,1))
if $piece(dados,Z,7)="" quit $$$ERROR(10000,"Pedido sem código de cliente: cadastre o cliente antes de enviar!")
if $piece(cfg,Z,4)="" quit $$$ERROR(10000,"Informe o Tipo de Nota na configuração de geração de pedido (WDOMTESTEPV100C)!")
;
set term=$job
kill tabCapa,tabErros,^mtempCCPVRG008ItensPed(term)
set tabCapa("codCliente")=$piece(dados,Z,7)
set tabCapa("codTipoNF")=$piece(cfg,Z,4)
set tabCapa("codTabelaPreco")=$select($piece(cfg,Z,5)'="":$piece(cfg,Z,5),1:9999)
set tabCapa("codRepresentante")=$piece(dados,Z,5)
set tabCapa("codCondVenda")=$piece(dados,Z,8)
set tabCapa("dataEmissao")=+$horolog
if $piece(dados,Z,9)'="" set tabCapa("dataPrevFat")=$piece(dados,Z,9)
if $piece(dados,Z,10)'="" set tabCapa("codTransportadora")=$piece(dados,Z,10)
set tabCapa("codPedidoCliente")=$$NumeroPedido(codEmpresa,codPedido)
;
set (codItem,seq)=0
for  set codItem=$order(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido,1,codItem)) quit:codItem=""  do
. set item=^WDOMTESTEPVPD(1,codEmpresa,1,codPedido,1,codItem),seq=seq+1
. set ^mtempCCPVRG008ItensPed(term,seq,"codProduto")=$piece(item,Z,3)
. set ^mtempCCPVRG008ItensPed(term,seq,"qtdPedida")=$justify($piece(item,Z,4)*1000,0,0)
. set ^mtempCCPVRG008ItensPed(term,seq,"precoUnit")=$justify($piece(item,Z,5)*100000,0,0)
if 'seq quit $$$ERROR(10000,"Pedido sem itens!")
;
set sc=$$GerarPedidoVenda^CCPVRG008(codEmpresa,term,.codPedidoConsistem,.tabCapa,.tabErros)
kill ^mtempCCPVRG008ItensPed(term)
if $$$ISERR(sc) quit sc
if $data(tabErros) set erro=$order(tabErros("")) quit $$$ERROR(10000,"Erro ao gerar o pedido: "_$get(tabErros(erro)))
;
quit $$$OK
;
; Excluir Pedido (Rascunho/Indeferido): grava o histórico e remove os índices
;
; set sc=$$ExcluirPedido^WDOMTESTEPV100ARG(codEmpresa,codPedido)
ExcluirPedido(codEmpresa,codPedido)	;
$$$VAR
new dados
;
if '$data(^WDOMTESTEPVPD(1,codEmpresa,1,+$get(codPedido))) quit $$$ERROR(10000,"Selecione um pedido!")
set dados=^WDOMTESTEPVPD(1,codEmpresa,1,codPedido)
if "RI"'[$piece(dados,Z,3) quit $$$ERROR(10000,"Somente pedido Rascunho ou Indeferido pode ser excluído!")
;
do GravarHistoricoPedido(codEmpresa,codPedido,"Excluir","")
if $piece(dados,Z,5)'="" do $$$KillG(^WDOMTESTEPVPD(1,codEmpresa,98,$piece(dados,Z,5),codPedido))
do $$$KillG(^WDOMTESTEPVPD(1,codEmpresa,2,codPedido))
do $$$KillG(^WDOMTESTEPVPD(1,codEmpresa,1,codPedido))
;
quit $$$OK
